    private static async Task<Access?> AccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, CancellationToken ct)
    {
        if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenantId) || !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membershipId) || !Guid.TryParse(http.User.FindFirstValue(ClaimTypes.NameIdentifier), out var actorId)) return null;
        var tenant = new TenantId(tenantId); var subject = await subjects.LoadAsync(tenant, membershipId, ct); if (subject is null) return null; var allowed = authorizer.Authorize(subject, permission, PermissionScope.ForTenant(tenant)); return new(tenant, actorId, allowed);
    }
    private static async Task<Access?> AccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid? legalEntityId, CancellationToken ct)
    {
        var access = await AccessAsync(http, subjects, authorizer, permission, ct);
        if (access is null || legalEntityId is null) return access;
        var tenantId = access.Tenant; var membershipId = Guid.Parse(http.User.FindFirstValue("membership_id")!); var subject = await subjects.LoadAsync(tenantId, membershipId, ct); if (subject is null) return null;
        var claimEntity = Guid.TryParse(http.User.FindFirstValue("legal_entity_id"), out var entity) ? entity : (Guid?)null;
        if (claimEntity is not null && claimEntity != legalEntityId) return new(access.Tenant, access.ActorId, false);
        return new(access.Tenant, access.ActorId, authorizer.Authorize(subject, permission, PermissionScope.ForLegalEntity(tenantId, new LegalEntityId(legalEntityId.Value))));
    }
    private static async Task<Access?> ResourceAccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Func<Task<Guid?>> legalEntity, CancellationToken ct)
    {
        var entity = await legalEntity();
        return await AccessAsync(http, subjects, authorizer, permission, entity, ct);
    }
    private static async Task<Access?> OfflineAccessAsync(HttpContext http, ServiceService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, OfflineCommandRequest request, CancellationToken ct)
    {
        var access = await ResourceAccessAsync(http, subjects, authorizer, "service.work.execute", () => request.WorkOrderId is { } workOrderId
            ? service.GetWorkOrderLegalEntityAsync(Tenant(http), workOrderId, ct)
            : request.VisitId is { } visitId
                ? service.GetVisitLegalEntityAsync(Tenant(http), visitId, ct)
                : Task.FromResult<Guid?>(null), ct);
        if (access is null || !access.Allowed) return access;
        var assigned = await service.IsActorAssignedAsync(access.Tenant, access.ActorId, request.WorkOrderId, request.VisitId, ct);
        return new(access.Tenant, access.ActorId, assigned);
    }
    private static async Task<Access?> MobileAccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct)
    {
        var access = await AccessAsync(http, subjects, authorizer, "service.work.read", ct);
        if (access is null || access.Allowed) return access;
        if (!Guid.TryParse(http.User.FindFirstValue("legal_entity_id"), out var legalEntityId)) return access;
        return await AccessAsync(http, subjects, authorizer, "service.work.read", legalEntityId, ct);
    }
    private static async Task<IResult> Execute<T>(HttpContext http, Access? access, Func<Task<T>> action, int status = StatusCodes.Status200OK) { if (access is null) return Results.Unauthorized(); if (!access.Allowed) return Results.Forbid(); try { var value = await action(); return status == StatusCodes.Status201Created ? Results.Created(http.Request.Path, value) : status == StatusCodes.Status202Accepted ? Results.Accepted(http.Request.Path, value) : Results.Ok(value); } catch (ServiceException ex) { var code = ex.Code; var statusCode = code.Contains("not_found", StringComparison.Ordinal) ? 404 : code.Contains("conflict", StringComparison.Ordinal) || code.Contains("duplicate", StringComparison.Ordinal) || code.Contains("concurrent", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: statusCode, title: code, extensions: new Dictionary<string, object?> { ["code"] = code }); } }
    private static TenantId Tenant(HttpContext http) => new(Guid.Parse(http.User.FindFirstValue("tenant_id")!));
    private static Guid Actor(HttpContext http) => Guid.Parse(http.User.FindFirstValue(ClaimTypes.NameIdentifier)!);
    private static Guid Membership(HttpContext http) => Guid.Parse(http.User.FindFirstValue("membership_id")!);
    private static Guid Correlation(HttpContext http) => Guid.TryParse(http.Request.Headers["X-Correlation-Id"], out var value) ? value : Guid.CreateVersion7();
    private sealed record Access(TenantId Tenant, Guid ActorId, bool Allowed);
}

